CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE source_type AS ENUM ('ESP32','MANUAL_CHEMICAL_TEST','EXTERNAL_TDS_METER','GOVERNMENT_CGWB','GOVERNMENT_JJM','OTHER_GOVERNMENT','DEMO','AI');
CREATE TYPE government_record_type AS ENUM ('LABORATORY_MEASUREMENT','CONTAMINATION_SUMMARY','TESTING_STATISTIC');
CREATE TABLE states (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL UNIQUE);
CREATE TABLE districts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), state_id uuid REFERENCES states(id), name text NOT NULL);
CREATE TABLE blocks (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), district_id uuid REFERENCES districts(id), name text NOT NULL);
CREATE TABLE gram_panchayats (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), block_id uuid REFERENCES blocks(id), name text NOT NULL);
CREATE TABLE villages (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), gram_panchayat_id uuid REFERENCES gram_panchayats(id), name text NOT NULL, latitude numeric, longitude numeric);
CREATE TABLE water_sources (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), village_id uuid REFERENCES villages(id), name text NOT NULL, source_type text NOT NULL, latitude numeric, longitude numeric);
CREATE TABLE devices (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), device_code text NOT NULL UNIQUE, water_source_id uuid REFERENCES water_sources(id), last_seen_at timestamptz, online boolean NOT NULL DEFAULT false);
CREATE TABLE parameters (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), code text NOT NULL UNIQUE, display_name text NOT NULL, default_unit text);
CREATE TABLE water_quality_standards (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), parameter_id uuid NOT NULL REFERENCES parameters(id), min_value numeric, max_value numeric, warning_value numeric, critical_value numeric, unit text, standard_kind text NOT NULL CHECK(standard_kind IN ('MONITORING_THRESHOLD','OFFICIAL_REFERENCE')), reference_source text NOT NULL, effective_date date, notes text);
CREATE TABLE sensor_readings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), device_id uuid NOT NULL REFERENCES devices(id), water_source_id uuid NOT NULL REFERENCES water_sources(id), temperature numeric NOT NULL, turbidity numeric NOT NULL, observed_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE manual_measurements (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), water_source_id uuid NOT NULL REFERENCES water_sources(id), parameter_id uuid NOT NULL REFERENCES parameters(id), value numeric NOT NULL, unit text NOT NULL, source source_type NOT NULL CHECK(source IN ('MANUAL_CHEMICAL_TEST','EXTERNAL_TDS_METER')), tested_at timestamptz NOT NULL, operator_name text, notes text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE government_datasets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), source_organization text NOT NULL, dataset_name text NOT NULL, dataset_year text, source_url text, imported_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE government_records (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), dataset_id uuid NOT NULL REFERENCES government_datasets(id) ON DELETE CASCADE, record_type government_record_type NOT NULL, parameter_id uuid NOT NULL REFERENCES parameters(id), value numeric, unit text, affected_village_count integer, state_name text, district_name text, block_name text, gram_panchayat_name text, village_name text, water_source_name text, sample_date date, latitude numeric, longitude numeric, original_row_reference text, notes text, imported_at timestamptz NOT NULL DEFAULT now(), CHECK ((record_type='LABORATORY_MEASUREMENT' AND value IS NOT NULL) OR (record_type<>'LABORATORY_MEASUREMENT' AND affected_village_count IS NOT NULL)));
CREATE TABLE alerts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), severity text NOT NULL, parameter_id uuid REFERENCES parameters(id), source source_type NOT NULL, water_source_id uuid REFERENCES water_sources(id), message text NOT NULL, recommended_action text NOT NULL, occurred_at timestamptz NOT NULL DEFAULT now(), acknowledged_at timestamptz);
CREATE TABLE ai_analyses (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), water_source_id uuid REFERENCES water_sources(id), request_data jsonb NOT NULL, response_data jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE pump_commands (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), device_id uuid REFERENCES devices(id), command text NOT NULL CHECK(command IN ('START','STOP')), status text NOT NULL DEFAULT 'PENDING', requested_at timestamptz NOT NULL DEFAULT now(), acknowledged_at timestamptz);
CREATE TABLE import_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), dataset_id uuid REFERENCES government_datasets(id), status text NOT NULL, total_rows integer NOT NULL DEFAULT 0, valid_rows integer NOT NULL DEFAULT 0, invalid_rows integer NOT NULL DEFAULT 0, duplicate_rows integer NOT NULL DEFAULT 0, imported_rows integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE import_errors (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), import_job_id uuid NOT NULL REFERENCES import_jobs(id) ON DELETE CASCADE, row_number integer NOT NULL, field_name text, message text NOT NULL, original_row jsonb);
CREATE INDEX government_records_filter_idx ON government_records(parameter_id, sample_date, dataset_id);
CREATE INDEX sensor_readings_source_time_idx ON sensor_readings(water_source_id, observed_at DESC);
